d="preview-vehicle-colour" readonly></label></div><div class="col-6"><label class="form-label">Year<input class="form-control" id="preview-vehicle-year" readonly></label></div><div class="col-6"><label class="form-label">Current Mileage (KM)<input class="form-control" id="preview-vehicle-mileage" readonly></label></div></div></div></div></section>
